        with pytest.raises(ValueError, match="timezone-aware"):
            svc.create("task", due_at=datetime(2025, 7, 1))

    def test_accepts_aware_due_at(self, svc):
        due = datetime(2025, 7, 1, tzinfo=timezone.utc)
        task = svc.create("task", due_at=due)
        assert task.due_at == due

    def test_normalizes_tags(self, svc):
        task = svc.create("task", tags=["  Work ", "work", "Home"])
        tag_names = [t.name for t in task.tags]
        assert tag_names == ["work", "home"]

    def test_rejects_non_datetime_due_at(self, svc):
        with pytest.raises(ValueError, match="must be a datetime"):
            svc.create("task", due_at="2025-07-01")  # type: ignore[arg-type]


