        task = Task(id=1, title="t", tags=[Tag("work")], created_at=now)
        repo.get.return_value = task
        result = svc.add_tags(1, ["Work", "home"])
        names = [t.name for t in result.tags]
        assert "work" in names
        assert "home" in names
        assert len(names) == 2


class TestRemoveTag:
    def test_removes_existing_tag(self, svc, repo, now):
        task = Task(id=1, title="t", tags=[Tag("work"), Tag("home")], created_at=now)
        repo.get.return_value = task
        result = svc.remove_tag(1, "work")
        assert all(t.name != "work" for t in result.tags)

