from __future__ import annotations

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 10, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        tags=tags or [],
        created_at=created_at or NOW,
    )


@pytest.fixture
def tasks():
    return [
        _task(1, "Alpha", priority=TaskPriority.HIGH,
              tags=[Tag("work")],
              created_at=datetime(2025, 6, 1, tzinfo=timezone.utc)),
        _task(2, "Beta", status=TaskStatus.DONE, priority=TaskPriority.LOW,
              created_at=datetime(2025, 6, 2, tzinfo=timezone.utc)),
        _task(3, "Gamma", priority=TaskPriority.MEDIUM,
              due_at=datetime(2025, 6, 5, tzinfo=timezone.utc),  # overdue
              tags=[Tag("home"), Tag("work")],
              created_at=datetime(2025, 6, 3, tzinfo=timezone.utc)),
        _task(4, "Delta", priority=TaskPriority.HIGH,
              due_at=datetime(2025, 7, 1, tzinfo=timezone.utc),  # not overdue
              created_at=datetime(2025, 6, 4, tzinfo=timezone.utc)),
    ]


class TestTaskQueryValidation:
    def test_rejects_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    def test_rejects_zero_limit(self):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=0)

    def test_rejects_limit_over_100(self):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=101)

    def test_rejects_negative_offset(self):
        with pytest.raises(TaskQueryError, match="offset must be"):
            TaskQuery(offset=-1)

    def test_normalizes_tag(self):
        q = TaskQuery(tag="  Work  ")
        assert q.tag == "work"

    def test_rejects_invalid_tag(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_blank_search_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_valid_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0


class TestFilterStatus:
    def test_filter_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert all(t.status == TaskStatus.PENDING for t in page.items)
        assert page.total == 3

    def test_filter_done(self, tasks):
