"""Tests for tasks_api.models."""

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTag:
    def test_normalizes_case_and_whitespace(self):
        t = Tag("  Hello ")
        assert t.name == "hello"

    def test_rejects_empty_string(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("")

    def test_rejects_whitespace_only(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_rejects_non_string(self):
        with pytest.raises(TypeError):
            Tag(123)  # type: ignore[arg-type]

    def test_rejects_too_long(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_allows_hyphens_and_underscores(self):
        t = Tag("my-tag_2")
        assert t.name == "my-tag_2"

    def test_rejects_special_characters(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("hello world")


class TestTaskPriority:
    def test_order_key(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) == 0
        assert TaskPriority.order_key(TaskPriority.MEDIUM) == 1
        assert TaskPriority.order_key(TaskPriority.LOW) == 2


class TestTaskIsOverdue:
    def test_overdue_when_past_due(self):
        now = datetime(2025, 6, 10, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=datetime(2025, 6, 5, tzinfo=timezone.utc))
        assert task.is_overdue(now) is True

    def test_not_overdue_when_future(self):
        now = datetime(2025, 6, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=datetime(2025, 6, 10, tzinfo=timezone.utc))
        assert task.is_overdue(now) is False

    def test_not_overdue_when_done(self):
        now = datetime(2025, 6, 10, tzinfo=timezone.utc)
        task = Task(
            id=1,
            title="t",
            status=TaskStatus.DONE,
            due_at=datetime(2025, 6, 5, tzinfo=timezone.utc),
        )
        assert task.is_overdue(now) is False

    def test_not_overdue_when_no_due_date(self):
        now = datetime(2025, 6, 10, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=None)
        assert task.is_overdue(now) is False

"""Tests for tasks_api.service (TaskService) with mocked repository."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone
from unittest.mock import Mock

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import TaskRepository
from tasks_api.service import TaskNotFoundError, TaskService


@pytest.fixture
def now():
    return datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


@pytest.fixture
def clock(now):
    return lambda: now


@pytest.fixture
def repo():
    mock = Mock(spec=TaskRepository)
    mock.next_id.return_value = 1
    return mock


@pytest.fixture
def svc(repo, clock):
    return TaskService(repo, now=clock, max_title_length=50)


class TestCreate:
    def test_creates_task_with_defaults(self, svc, repo, now):
        repo.next_id.return_value = 42
        task = svc.create("Buy milk")
        assert task.id == 42
        assert task.title == "Buy milk"
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.created_at == now
        repo.add.assert_called_once_with(task)

    def test_strips_title_whitespace(self, svc, repo):
        task = svc.create("  padded  ")
        assert task.title == "padded"

    def test_rejects_empty_title(self, svc):
        with pytest.raises(ValueError, match="must not be empty"):
            svc.create("")

    def test_rejects_whitespace_only_title(self, svc):
        with pytest.raises(ValueError, match="must not be empty"):
            svc.create("   ")

    def test_rejects_non_string_title(self, svc):
        with pytest.raises(ValueError, match="must be a string"):
            svc.create(123)  # type: ignore[arg-type]

    def test_rejects_title_too_long(self, svc):
        with pytest.raises(ValueError, match="50 characters"):
            svc.create("x" * 51)

    def test_accepts_max_length_title(self, svc):
        task = svc.create("x" * 50)
        assert task.title == "x" * 50

    def test_rejects_invalid_priority(self, svc):
        with pytest.raises(ValueError, match="TaskPriority"):
            svc.create("task", priority="high")  # type: ignore[arg-type]

    def test_accepts_valid_priority(self, svc):
        task = svc.create("task", priority=TaskPriority.HIGH)
        assert task.priority == TaskPriority.HIGH

    def test_rejects_naive_due_at(self, svc):
        with pytest.raises(ValueError, match="timezone-aware"):
            svc.create("task", due_at=datetime(2025, 7, 1))

    def test_accepts_aware_due_at(self, svc):
        due = datetime(2025, 7, 1, tzinfo=timezone.utc)
        task = svc.create("task", due_at=due)
        assert task.due_at == due

    def test_normalizes_tags(self, svc):
        task = svc.create("task", tags=["  Work ", "work", "Home"])
        tag_names = [t.name for t in task.tags]
        assert tag_names == ["work", "home"]

    def test_rejects_non_datetime_due_at(self, svc):
        with pytest.raises(ValueError, match="must be a datetime"):
            svc.create("task", due_at="2025-07-01")  # type: ignore[arg-type]


class TestGet:
    def test_returns_task(self, svc, repo, now):
        task = Task(id=1, title="t", created_at=now)
        repo.get.return_value = task
        assert svc.get(1) == task

    def test_raises_not_found(self, svc, repo):
        repo.get.return_value = None
        with pytest.raises(TaskNotFoundError):
            svc.get(999)


class TestComplete:
    def test_completes_pending_task(self, svc, repo, now):
        task = Task(id=1, title="t", status=TaskStatus.PENDING, created_at=now)
        repo.get.return_value = task
        result = svc.complete(1)
        assert result.status == TaskStatus.DONE
        assert result.completed_at == now
        repo.update.assert_called_once()

    def test_rejects_already_done(self, svc, repo, now):
        task = Task(id=1, title="t", status=TaskStatus.DONE, created_at=now)
        repo.get.return_value = task
        with pytest.raises(ValueError, match="already done"):
            svc.complete(1)


class TestReopen:
    def test_reopens_done_task(self, svc, repo, now):
        task = Task(
            id=1, title="t", status=TaskStatus.DONE,
            completed_at=now, created_at=now
        )
        repo.get.return_value = task
        result = svc.reopen(1)
        assert result.status == TaskStatus.PENDING
        assert result.completed_at is None
        repo.update.assert_called_once()

    def test_rejects_already_pending(self, svc, repo, now):
        task = Task(id=1, title="t", status=TaskStatus.PENDING, created_at=now)
        repo.get.return_value = task
        with pytest.raises(ValueError, match="already pending"):
            svc.reopen(1)


class TestDelete:
    def test_deletes_existing_task(self, svc, repo):
        repo.delete.return_value = True
        svc.delete(1)
        repo.delete.assert_called_once_with(1)

    def test_raises_not_found(self, svc, repo):
        repo.delete.return_value = False
        with pytest.raises(TaskNotFoundError):
            svc.delete(999)


class TestSetPriority:
    def test_sets_priority(self, svc, repo, now):
        task = Task(id=1, title="t", priority=TaskPriority.LOW, created_at=now)
        repo.get.return_value = task
        result = svc.set_priority(1, TaskPriority.HIGH)
