class TestSetDueAt:
    def test_sets_due_at(self, svc, repo, now):
        task = Task(id=1, title="t", created_at=now)
        repo.get.return_value = task
        new_due = datetime(2025, 8, 1, tzinfo=timezone.utc)
        result = svc.set_due_at(1, new_due)
